44	const PROCESSING_FEE = 5;
45	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
46	
47	const BASE_PREMIUMS = {
48	  sword: 100,
49	  amulet: 60,
50	  staff: 80,
51	  potion: 40,
52	  rune: 25,
53	  moonstone: 25,
54	} as const satisfies Record<string, number>;
55	
56	export type InsurableItemType = keyof typeof BASE_PREMIUMS;
57	
58	const basePremiumForType = (type: string): number =>
59	  BASE_PREMIUMS[type as InsurableItemType];
60	
61	const BLOCK_SIZE = 3;
62	const BLOCK_PREMIUM = 60;
63	
64	// Items of one type, quoted together. A group of exactly 3 forms a building
65	// block and is offered at a flat base premium; any other size is priced per
66	// item. "Alike" means the same item type — 2 runes + 1 moonstone is two
67	// groups, so neither is a block.
68	type AlikeGroup = [type: string, items: Item[]];
69	
70	const intoAlikeGroups = (items: Item[]): AlikeGroup[] => {
71	  const groups = new Map<string, Item[]>();
72	  for (const item of items) {
73	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
74	  }
75	  return [...groups];
76	};
77	
78	const isBuildingBlock = ([, items]: AlikeGroup): boolean =>
79	  items.length === BLOCK_SIZE;
80	
81	const basePremiumForGroup = (group: AlikeGroup): number => {
82	  const [type, items] = group;
83	  return isBuildingBlock(group)
84	    ? BLOCK_PREMIUM
85	    : items.length * basePremiumForType(type);
86	};
87	
88	const sumBasePremiums = (items: Item[]): number =>
89	  intoAlikeGroups(items).reduce(
90	    (total, group) => total + basePremiumForGroup(group),
91	    0,
92	  );
93	
94	const CURSE_SURCHARGE_RATE = 0.5;
95	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
96	const HIGH_ENCHANTMENT_THRESHOLD = 5;
97	
98	const isHighlyEnchanted = (item: Item): boolean =>
99	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
100	
101	// Item-specific modifiers apply to the base premium of the affected item, not
102	// to the policy total.
103	const surchargeRateForItem = (item: Item): number =>
104	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
105	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
106	
107	const sumItemSurcharges = (items: Item[]): number =>
108	  items.reduce(
109	    (total, item) =>
110	      total + basePremiumForType(item.type) * surchargeRateForItem(item),
111	    0,
112	  );
113	
114	// Premiums are rounded up, in the MHPCO's favour; only the final premium is
115	// rounded, intermediate amounts stay fractional.
116	const roundInMHPCOsFavour = Math.ceil;
117	
118	const quotePremium = (items: Item[]): number => {
119	  const basePremium = sumBasePremiums(items);
120	  const itemSurcharges = sumItemSurcharges(items);
121	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
122	  return roundInMHPCOsFavour(
123	    basePremium + itemSurcharges + firstInsuranceSurcharge + PROCESSING_FEE,
124	  );
125	};
126	
127	const runStep = (step: Step): QuoteResult | ClaimResult => {
128	  switch (step.op) {
129	    case "quote":
130	      return { premium: quotePremium(step.items) };
131	    case "claim":
132	      throw new Error("claim steps are not supported yet");
133	  }
134	};
135	
136	export const runScenario = (scenario: Scenario): ScenarioResults => ({
137	  results: scenario.steps.map(runStep),
138	});
